test('createInvoice rejects invalid discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 150 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
